import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
  JxSnip,
} from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  postalCode: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    fullName: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    postalCode: '',
  });

  const updateField = (field: keyof RegistrationData) => (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const canGoNext = () => {
    if (step === 0) {
      return data.fullName.trim().length > 0 && data.email.trim().length > 0;
    }
    if (step === 1) {
      return data.address.trim().length > 0 && data.city.trim().length > 0;
    }
    return true;
  };

  const goBack = () => setStep((prev) => Math.max(prev - 1, 0));
  const goNext = () => setStep((prev) => Math.min(prev + 1, steps.length - 1));

  const handleSubmit = () => {
    onSubmit(data);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '480px',
        padding: '24px',
        background: 'var(--jx-surface)',
        borderRadius: 'var(--jx-r-lg)',
        border: '1px solid var(--jx-border)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={data.fullName}
            onChange={updateField('fullName')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={updateField('email')}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            value={data.phone}
            onChange={updateField('phone')}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Адрес"
            required
            value={data.address}
            onChange={updateField('address')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={updateField('city')}
          />
          <JxInputField
            label="Почтовый индекс"
            value={data.postalCode}
            onChange={updateField('postalCode')}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <JxDivider label="Контакты" />
          <p style={{ color: 'var(--jx-text-2)', margin: 0 }}>
            Имя: <JxSnip>{data.fullName || '—'}</JxSnip>
          </p>
          <p style={{ color: 'var(--jx-text-2)', margin: 0 }}>
            Почта: <JxSnip>{data.email || '—'}</JxSnip>
          </p>
          <p style={{ color: 'var(--jx-text-2)', margin: 0 }}>
            Телефон: <JxSnip>{data.phone || '—'}</JxSnip>
          </p>
          <JxDivider label="Адрес" />
          <p style={{ color: 'var(--jx-text-2)', margin: 0 }}>
            Адрес: <JxSnip>{data.address || '—'}</JxSnip>
          </p>
          <p style={{ color: 'var(--jx-text-2)', margin: 0 }}>
            Город: <JxSnip>{data.city || '—'}</JxSnip>
          </p>
          <p style={{ color: 'var(--jx-text-2)', margin: 0 }}>
            Индекс: <JxSnip>{data.postalCode || '—'}</JxSnip>
          </p>
        </div>
      ) : null}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext()} onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

